ls /sdcard/Nexus_Brain/nexus_vault/*/Master_Sales_* /sdcard/Nexus_Brain/nexus_vault/*/Master_Trust_Building_* /sdcard/Nexus_Brain/nexus_vault/*/Master_Content_Repurposing_* /sdcard/Nexus_Brain/nexus_vault/*/Master_Strategic_Operations_* 2>/dev/null; echo "---"; python3 -c "
import os
for f in ['Master_Sales_Psychology_Tactics', 'Master_Trust_Building_Credibility', 'Master_Advanced_Sales_Mechanisms', 'Master_Content_Repurposing_Methods', 'Master_Strategic_Operations_Workflow']:
    found = False
    for root, dirs, files in os.walk('/sdcard/Nexus_Brain/nexus_vault/'):
        for fn in files:
            if fn.startswith(f):
                print(f'✅ {os.path.join(root, fn)}')
                found = True
    if not found:
        print(f'❌ {f} — NOT FOUND')
"

